struct Edge {
  int from, to;
  long long capacity, currentFlow;
  Edge() {}
  Edge(int u, int v, long long cap): from(u), to(v), capacity(cap), currentFlow(0) {}
};

struct FlowNetwork {
  int totalNodes;
  vector<Edge> edges;
  vector<vector<int>> adj;
  vector<int> level, ptr;

  FlowNetwork(int N): totalNodes(N), edges(), adj(N), level(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      adj[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      adj[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(level.begin(), level.end(), totalNodes + 1);
    level[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int e_idx: adj[u]) {
        Edge &e = edges[e_idx];
        if (e.currentFlow < e.capacity && level[e.v] > level[e.u] + 1) {
          level[e.v] = level[e.u] + 1;
          q.push(e.v);
        }
      }
    }
    return level[T] != totalNodes + 1;
  }

  long long sendFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)adj[u].size(); ++i) {
      Edge &e = edges[adj[u][i]];
      Edge &oe = edges[adj[u][i]^1];
      if (level[e.v] == level[e.u] + 1) {
        long long amt = e.capacity - e.currentFlow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = sendFlow(e.v, T, amt);
        if (pushed > 0) {
          e.currentFlow += pushed;
          oe.currentFlow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long maxFlow(int S, int T) {
    long long total = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = sendFlow(S, T))
        total += flow;
    }
    return total;
  }
};

