import java.util.*;
import java.io.*;

public class Main {
    static char[][] maze1 = new char[15][15];
    static char[][] maze2 = new char[15][15];
    static int[][] move = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    static int[][][] node_idx = new int[65][15][15];
    static int[][] flow_cap = new int[15][15];
    static int node_id = 1;

    static class Edge {
        int from, to;
        long capacity, currentFlow;

        Edge() {}

        Edge(int u, int v, long cap) {
            this.from = u;
            this.to = v;
            this.capacity = cap;
            this.currentFlow = 0;
        }
    }

    static class FlowNetwork {
        int totalNodes;
        List<Edge> edges = new ArrayList<>();
        List<List<Integer>> adj;
        int[] level, ptr;

        FlowNetwork(int N) {
            this.totalNodes = N;
            adj = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                adj.add(new ArrayList<>());
            }
            level = new int[N];
            ptr = new int[N];
        }

        void addEdge(int u, int v, long cap) {
            if (u != v) {
                edges.add(new Edge(u, v, cap));
                adj.get(u).add(edges.size() - 1);
                edges.add(new Edge(v, u, 0));
                adj.get(v).add(edges.size() - 1);
            }
        }

        boolean buildLevelGraph(int S, int T) {
            Arrays.fill(level, totalNodes + 1);
            level[S] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(S);
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == T) break;
                for (int e_idx : adj.get(u)) {
                    Edge e = edges.get(e_idx);
                    if (e.currentFlow < e.capacity && level[e.to] > level[e.from] + 1) {
                        level[e.to] = level[e.from] + 1;
                        q.offer(e.to);
                    }
                }
            }
            return level[T] != totalNodes + 1;
        }

        long sendFlow(int u, int T, long flow) {
            if (u == T || flow == 0) return flow;
            for (; ptr[u] < adj.get(u).size(); ptr[u]++) {
                int e_idx = adj.get(u).get(ptr[u]);
                Edge e = edges.get(e_idx);
                Edge oe = edges.get(e_idx ^ 1);
                if (level[e.to] == level[e.from] + 1) {
                    long amt = e.capacity - e.currentFlow;
                    if (flow != -1 && amt > flow) amt = flow;
                    long pushed = sendFlow(e.to, T, amt);
                    if (pushed > 0) {
                        e.currentFlow += pushed;
                        oe.currentFlow -= pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        }

        long maxFlow(int S, int T) {
            long total = 0;
            while (buildLevelGraph(S, T)) {
                Arrays.fill(ptr, 0);
                long flow;
                while ((flow = sendFlow(S, T, -1)) > 0) {
                    total += flow;
                }
            }
            return total;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                maze1[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 0; i <= t + 1; i++) {
            for (int j = 1; j <= n; j++) {
                String line = br.readLine();
                for (int k = 1; k <= n; k++) {
                    maze2[j][k] = line.charAt(k - 1);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                node_idx[0][i][j] = node_id++;
            }
        }
        node_id++;
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                maze2[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                flow_cap[i][j] = -1;
            }
        }

        Queue<int[]> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    flow_cap[i][j] = 0;
                }
            }
        }

        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int y = pos[0], x = pos[1];
            for (int i = 0; i < 4; i++) {
                int ny = y + move[i][0], nx = x + move[i][1];
                if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && maze1[ny][nx] != 'Y' && flow_cap[ny][nx] == -1) {
                    flow_cap[ny][nx] = flow_cap[y][x] + 1;
                    q.offer(new int[]{ny, nx});
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (flow_cap[i][j] == -1 || flow_cap[i][j] > t) {
                    flow_cap[i][j] = 1000000000;
                }
            }
        }

        int s = 0;
        int t_node = node_id - 1;
        FlowNetwork network = new FlowNetwork(node_id);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] >= '1' && maze1[i][j] <= '9') {
                    network.addEdge(s, node_idx[0][i][j], maze1[i][j] - '0');
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] == 'Y' || maze1[i][j] == 'Z') continue;
                for (int k = 0; k < 4; k++) {
                    int ny = i + move[k][0], nx = j + move[k][1];
                    if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && maze1[ny][nx] != 'Y' && maze1[ny][nx] != 'Z') {
                        for (int x = 0; x < t; x++) {
                            if (flow_cap[ny][nx] >= x + 1 && flow_cap[i][j] > x) {
                                network.addEdge(node_idx[x][i][j], node_idx[x + 1][ny][nx], 1000);
                            }
                        }
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] == 'Y' || maze1[i][j] == 'Z') continue;
                for (int x = 0; x <= t; x++) {
                    if (maze2[i][j] >= '1' && maze2[i][j] <= '9') {
                        network.addEdge(node_idx[x][i][j], node_idx[t + 1][i][j], maze2[i][j] - '0');
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (maze1[i][j] == 'Y' || maze1[i][j] == 'Z') continue;
                if (maze2[i][j] >= '1' && maze2[i][j] <= '9') {
                    network.addEdge(node_idx[t + 1][i][j], t_node, maze2[i][j] - '0');
                }
            }
        }

        System.out.println(network.maxFlow(s, t_node));
    }
}
